// Token cache functions
export function saveToken\(tokenData: TokenData\): void {
  localStorage.setItem\(TOKEN_STORAGE_KEY, JSON.stringify\(tokenData\)\);
}

export function getToken\(\): TokenData | null {
  const stored = localStorage.getItem\(TOKEN_STORAGE_KEY\);
  if \(!stored\) return null;
  try {
    const parsed: TokenData = JSON.parse\(stored\);
    if \(parsed.expiresAt <= Date.now\(\)\) {
      clearToken\(\);
      return null;
    }
    return parsed;
  } catch {
    clearToken\(\);
    return null;
  }
}

export function clearToken\(\): void {
  localStorage.removeItem\(TOKEN_STORAGE_KEY\);
}

export function isTokenValid\(\): boolean {
  return getToken\(\) !== null;
}

// signIn integration - after receiving access_token:
const expiresAt = Date.now\(\) + \(response.expires_in ?? 3600\) * 1000;
saveToken\({ accessToken: response.access_token, expiresAt }\);

// signOut integration - after revoke:
clearToken\(\);

// initializeGoogleAPI integration - after GIS init:
const cachedToken = getToken\(\);
if \(cachedToken\) {
  gapi.client.setToken\({ access_token: cachedToken.accessToken }\);
  fetchUserInfo\(cachedToken.accessToken\)
    .then\(\(userInfo\) => {
      notifyAuthStateChange\({ isSignedIn: true, user: userInfo }\);
    }\)
    .catch\(\(\) => {
      clearToken\(\);
      gapi.client.setToken\(null\);
    }\);
}
